<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';

use School\Core\SchoolAuth;
use School\Core\SchoolDatabase;
use School\Services\AuditService;

SchoolAuth::requireLogin();
$user=SchoolAuth::user();
$role=school_current_role($user);
$studentId=(int)($_GET['id']??0);
if(!$studentId){http_response_code(404);exit('Student record not found.');}
$pdo=SchoolDatabase::connection();
$q=$pdo->prepare('SELECT * FROM students WHERE id=:id LIMIT 1');
$q->execute(['id'=>$studentId]);
$student=$q->fetch();
if(!$student){http_response_code(404);exit('Student record not found.');}
$activeQuery=$pdo->prepare("SELECT en.class_group_id,en.academic_year_id,en.stream_id,c.name class_name,y.name year_name,st.name stream_name FROM enrollments en JOIN class_groups c ON c.id=en.class_group_id JOIN academic_years y ON y.id=en.academic_year_id LEFT JOIN streams st ON st.id=en.stream_id WHERE en.student_id=:student AND en.status='active' ORDER BY y.starts_on DESC LIMIT 1");
$activeQuery->execute(['student'=>$studentId]);
$active=$activeQuery->fetch()?:null;
if($role==='student')$allowed=SchoolAuth::can('portal.self',['student_id'=>$studentId]);
else $allowed=SchoolAuth::hasPermission('students.view')&&SchoolAuth::can('students.view',['student_id'=>$studentId,'class_group_id'=>(int)($active['class_group_id']??0),'academic_year_id'=>(int)($active['academic_year_id']??0)]);
if(!$allowed){http_response_code(403);exit('Student access is not permitted.');}
$canManage=SchoolAuth::hasPermission('students.manage');
$error='';$message='';

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!$canManage){http_response_code(403);exit('Student changes are not permitted.');}
    elseif(!SchoolAuth::verifyCsrf())$error='Your session expired. Please try again.';
    else try{
        $action=(string)($_POST['action']??'update');
        if($action==='promote'){
            $classId=(int)($_POST['class_group_id']??0);$streamId=(int)($_POST['stream_id']??0);
            if(!$classId)throw new RuntimeException('Choose the next academic year class.');
            SchoolDatabase::transaction(function(PDO $pdo)use($studentId,$classId,$streamId,$user):void{
                $q=$pdo->prepare("SELECT status FROM students WHERE id=:id FOR UPDATE");$q->execute(['id'=>$studentId]);if($q->fetchColumn()!=='active')throw new RuntimeException('Only active students can be enrolled in another year.');
                $q=$pdo->prepare("SELECT c.id,c.academic_year_id,c.capacity,y.name year_name,y.starts_on,y.status year_status FROM class_groups c JOIN academic_years y ON y.id=c.academic_year_id WHERE c.id=:class");$q->execute(['class'=>$classId]);$target=$q->fetch();if(!$target||!in_array($target['year_status'],['active','planned'],true))throw new RuntimeException('Choose a class in an active or planned academic year.');
                if($streamId){$q=$pdo->prepare('SELECT COUNT(*) FROM streams WHERE id=:stream AND class_group_id=:class');$q->execute(['stream'=>$streamId,'class'=>$classId]);if(!(int)$q->fetchColumn())throw new RuntimeException('The selected stream does not belong to that class.');}
                $q=$pdo->prepare("SELECT en.id,en.academic_year_id,y.starts_on FROM enrollments en JOIN academic_years y ON y.id=en.academic_year_id WHERE en.student_id=:student AND en.status='active' FOR UPDATE");$q->execute(['student'=>$studentId]);$current=$q->fetch();if($current&&(int)$current['academic_year_id']===(int)$target['academic_year_id'])throw new RuntimeException('The student already has an active enrollment in that year. Same-year transfers must be recorded by the school office.');if($current&&$target['starts_on']<$current['starts_on'])throw new RuntimeException('The target academic year must follow the current enrollment.');
                $q=$pdo->prepare('SELECT COUNT(*) FROM enrollments WHERE student_id=:student AND academic_year_id=:year');$q->execute(['student'=>$studentId,'year'=>(int)$target['academic_year_id']]);if((int)$q->fetchColumn())throw new RuntimeException('An enrollment already exists for the target year.');
                if($target['capacity']!==null){$q=$pdo->prepare("SELECT COUNT(*) FROM enrollments WHERE class_group_id=:class AND status='active'");$q->execute(['class'=>$classId]);if((int)$q->fetchColumn()>=(int)$target['capacity'])throw new RuntimeException('The selected class has reached its configured capacity.');}
                if($current){$q=$pdo->prepare("UPDATE enrollments SET status='completed',ended_at=DATE_SUB(:start,INTERVAL 1 DAY) WHERE id=:id");$q->execute(['start'=>$target['starts_on'],'id'=>(int)$current['id']]);}
                $q=$pdo->prepare("INSERT INTO enrollments (student_id,academic_year_id,class_group_id,stream_id,status,started_at) VALUES (:student,:year,:class,:stream,'active',:start)");$q->execute(['student'=>$studentId,'year'=>(int)$target['academic_year_id'],'class'=>$classId,'stream'=>$streamId?:null,'start'=>$target['starts_on']]);
                (new AuditService())->record((int)$user['id'],'student.enrollment.create','enrollments',(int)$pdo->lastInsertId(),['student_id'=>$studentId,'target_year_id'=>(int)$target['academic_year_id'],'class_group_id'=>$classId]);
            });
            school_flash('success','Enrollment added for the next academic year.');header('Location: '.SCHOOL_BASE_URL.'students/record.php?id='.$studentId);exit;
        }
        if($action!=='update')throw new RuntimeException('That student action is not available.');
        $name=trim((string)($_POST['full_name']??''));$dob=(string)($_POST['date_of_birth']??'');$gender=(string)($_POST['gender']??'undisclosed');$admissionDate=(string)($_POST['admission_date']??'');$status=(string)($_POST['status']??'');
        if($name===''||mb_strlen($name)>180||!in_array($gender,['female','male','other','undisclosed'],true)||!in_array($status,['active','withdrawn','graduated','archived'],true)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$admissionDate)||($dob!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$dob)))throw new RuntimeException('Check the student name, dates, gender and status.');
        $previousStatus=$student['status'];
        SchoolDatabase::transaction(function(PDO $pdo)use($studentId,$name,$dob,$gender,$admissionDate,$status,$user,$previousStatus):void{
            $q=$pdo->prepare('UPDATE students SET full_name=:name,date_of_birth=:dob,gender=:gender,admission_date=:admitted,status=:status WHERE id=:id');$q->execute(['name'=>$name,'dob'=>$dob?:null,'gender'=>$gender,'admitted'=>$admissionDate,'status'=>$status,'id'=>$studentId]);
            if($status!=='active'){$enrollmentStatus=$status==='withdrawn'?'withdrawn':'completed';$q=$pdo->prepare("UPDATE enrollments SET status=:status,ended_at=:ended WHERE student_id=:student AND status='active'");$q->execute(['status'=>$enrollmentStatus,'ended'=>date('Y-m-d'),'student'=>$studentId]);}
            (new AuditService())->record((int)$user['id'],'student.update','students',$studentId,['previous_status'=>$previousStatus,'new_status'=>$status]);
        });
        $message='Student record updated.';$q=$pdo->prepare('SELECT * FROM students WHERE id=:id');$q->execute(['id'=>$studentId]);$student=$q->fetch();$activeQuery->execute(['student'=>$studentId]);$active=$activeQuery->fetch()?:null;
    }catch(Throwable $exception){$error=$exception instanceof PDOException?'That student change conflicts with an existing record.':$exception->getMessage();}
}

$q=$pdo->prepare('SELECT en.status,en.started_at,en.ended_at,c.name class_name,y.name year_name,st.name stream_name FROM enrollments en JOIN class_groups c ON c.id=en.class_group_id JOIN academic_years y ON y.id=en.academic_year_id LEFT JOIN streams st ON st.id=en.stream_id WHERE en.student_id=:student ORDER BY y.starts_on DESC');$q->execute(['student'=>$studentId]);$history=$q->fetchAll();
$targetClasses=$canManage?$pdo->query("SELECT c.id,c.name,c.academic_year_id,c.capacity,y.name year_name,y.starts_on FROM class_groups c JOIN academic_years y ON y.id=c.academic_year_id WHERE y.status IN ('active','planned') ORDER BY y.starts_on,c.name")->fetchAll():[];
$streams=$canManage?$pdo->query('SELECT id,class_group_id,name FROM streams ORDER BY name')->fetchAll():[];
$schoolName=(string)($pdo->query('SELECT name FROM school_profile ORDER BY id LIMIT 1')->fetchColumn()?:'School Management');$schoolRole=$role;$pageTitle='Student record';require dirname(__DIR__).'/includes/header.php';
?>
<div class="page-head"><div><h4><?= e($student['full_name']) ?></h4><p><?= e($student['admission_number'].' · '.($active['class_name']??'Not enrolled').($active['stream_name']?' · '.$active['stream_name']:'')) ?></p></div><div class="page-actions"><a href="<?= SCHOOL_BASE_URL ?>students/index.php" class="btn btn-outline-secondary btn-sm"><i class="bi bi-arrow-left me-1"></i>Student register</a><?php if($canManage||in_array($role,['parent_guardian','student'],true)): ?><a href="<?= SCHOOL_BASE_URL ?>students/documents.php?id=<?= $studentId ?>" class="btn btn-outline-primary btn-sm"><i class="bi bi-folder2-open me-1"></i>Documents</a><?php endif; ?><div class="dropdown d-inline-block"><button class="btn btn-outline-primary btn-sm dropdown-toggle" type="button" data-bs-toggle="dropdown" aria-expanded="false"><i class="bi bi-file-earmark-pdf me-1"></i>PDF</button><ul class="dropdown-menu dropdown-menu-end"><li><a class="dropdown-item" href="<?= SCHOOL_BASE_URL ?>reports/pdf.php?type=transcript&amp;student_id=<?= $studentId ?>">Academic transcript</a></li><li><a class="dropdown-item" href="<?= SCHOOL_BASE_URL ?>reports/pdf.php?type=admission_letter&amp;student_id=<?= $studentId ?>">Admission letter</a></li><li><a class="dropdown-item" href="<?= SCHOOL_BASE_URL ?>reports/pdf.php?type=id_cards&amp;student_id=<?= $studentId ?>">Learner ID card</a></li><?php if(SchoolAuth::hasPermission('finance.view')||in_array($role,['parent_guardian','student'],true)): ?><li><a class="dropdown-item" href="<?= SCHOOL_BASE_URL ?>reports/pdf.php?type=fee_statement&amp;student_id=<?= $studentId ?>">Fee statement</a></li><?php endif; ?></ul></div></div></div><?php foreach(school_take_flashes() as $f): ?><div class="alert alert-<?= e($f['type']) ?>"><?= e($f['message']) ?></div><?php endforeach; ?><?php if($message!==''): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><?php if($error!==''): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<div class="row g-3 mb-3"><div class="col-xl-8"><div class="card"><div class="card-header"><span class="card-title-sm"><i class="bi bi-person-vcard me-1"></i><?= $canManage?'Student details':'School record' ?></span></div><div class="card-body"><?php if($canManage): ?><form method="post" class="row g-3"><?= SchoolAuth::csrfField() ?><input type="hidden" name="action" value="update"><div class="col-md-8"><label class="form-label">Full name</label><input class="form-control" name="full_name" maxlength="180" value="<?= e($student['full_name']) ?>" required></div><div class="col-md-4"><label class="form-label">Admission number</label><input class="form-control" value="<?= e($student['admission_number']) ?>" disabled></div><div class="col-md-4"><label class="form-label">Date of birth</label><input class="form-control" name="date_of_birth" type="date" value="<?= e($student['date_of_birth']??'') ?>"></div><div class="col-md-4"><label class="form-label">Admission date</label><input class="form-control" name="admission_date" type="date" value="<?= e($student['admission_date']) ?>" required></div><div class="col-md-4"><label class="form-label">Gender</label><select class="form-select" name="gender"><?php foreach(['undisclosed'=>'Prefer not to say','female'=>'Female','male'=>'Male','other'=>'Other'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $student['gender']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['active'=>'Active','withdrawn'=>'Withdrawn','graduated'=>'Graduated','archived'=>'Archived'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $student['status']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="col-12"><button class="btn btn-primary btn-sm"><i class="bi bi-check2 me-1"></i>Save changes</button></div></form><?php else: ?><dl class="row mb-0"><dt class="col-sm-4">Admission number</dt><dd class="col-sm-8"><?= e($student['admission_number']) ?></dd><dt class="col-sm-4">Class</dt><dd class="col-sm-8"><?= e($active?($active['year_name'].' · '.$active['class_name'].($active['stream_name']?' · '.$active['stream_name']:'')):'Not enrolled') ?></dd><dt class="col-sm-4">Status</dt><dd class="col-sm-8"><?= e(ucfirst($student['status'])) ?></dd><dt class="col-sm-4">Admission date</dt><dd class="col-sm-8"><?= e(formatDate($student['admission_date'])) ?></dd></dl><?php endif; ?></div></div></div><div class="col-xl-4"><div class="card"><div class="card-header"><span class="card-title-sm"><i class="bi bi-shield-lock me-1"></i>Access and history</span></div><div class="card-body small text-muted">Student changes are permission checked and audited. New-year enrollment preserves prior academic-year history; same-year class transfers require a separate office workflow.</div></div></div></div>
<div class="card mb-3"><div class="card-header"><span class="card-title-sm"><i class="bi bi-clock-history me-1"></i>Enrollment history</span></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Academic year</th><th>Class</th><th>Stream</th><th>Started</th><th>Ended</th><th>Status</th></tr></thead><tbody><?php foreach($history as $entry): ?><tr><td><?= e($entry['year_name']) ?></td><td><?= e($entry['class_name']) ?></td><td><?= e($entry['stream_name']??'—') ?></td><td><?= e(formatDate($entry['started_at'])) ?></td><td><?= e(formatDate($entry['ended_at'])) ?></td><td><?= e(ucfirst($entry['status'])) ?></td></tr><?php endforeach; ?><?php if(!$history): ?><tr><td colspan="6" class="text-center text-muted py-3">No enrollment history.</td></tr><?php endif; ?></tbody></table></div></div>
<?php if($canManage&&$student['status']==='active'): ?><div class="card"><div class="card-header"><span class="card-title-sm"><i class="bi bi-arrow-up-right-circle me-1"></i>Enroll in another academic year</span></div><div class="card-body"><form method="post" class="row g-2 align-items-end"><?= SchoolAuth::csrfField() ?><input type="hidden" name="action" value="promote"><div class="col-md-6"><label class="form-label">Next-year class</label><select name="class_group_id" id="promotionClass" class="form-select" required><option value="">Choose class</option><?php foreach($targetClasses as $class): ?><option value="<?= (int)$class['id'] ?>"><?= e($class['year_name'].' · '.$class['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Stream</label><select name="stream_id" id="promotionStream" class="form-select"><option value="0">No stream</option><?php foreach($streams as $stream): ?><option data-class="<?= (int)$stream['class_group_id'] ?>" value="<?= (int)$stream['id'] ?>"><?= e($stream['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-outline-primary w-100"><i class="bi bi-check2 me-1"></i>Enroll</button></div></form><div class="form-text">This adds an enrollment for a different active or planned year and closes the prior active enrollment. It does not change an enrollment within the same year.</div></div></div><script>document.getElementById('promotionClass').addEventListener('change',function(){const id=this.value;const select=document.getElementById('promotionStream');Array.from(select.options).forEach((option,index)=>{if(index>0)option.hidden=option.dataset.class!==id;});select.value='0';});</script><?php endif; ?>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
